import type { ComponentPropsWithoutRef } from "react";
import { cn } from "../../lib/cn";
import "../../styles/pagination.css";

export interface PaginationProps extends Omit<ComponentPropsWithoutRef<"nav">, "onChange"> {
  /** Current page, starting at 1. */
  page: number;
  pageCount: number;
  onPageChange: (page: number) => void;
  /** How many numbers to show on each side of the current page. */
  siblings?: number;
}

/** Numbered pages with previous and next. Every control has a name for screen readers. */
export function Pagination({ page, pageCount, onPageChange, siblings = 1, className, ...props }: PaginationProps) {
  const pages = buildRange(page, pageCount, siblings);
  return (
    <nav aria-label="Pagination" className={cn("eui-pagination", className)} {...props}>
      <ul className="eui-pagination__list">
        <li>
          <button
            type="button"
            className="eui-pagination__control"
            disabled={page <= 1}
            onClick={() => onPageChange(page - 1)}
          >
            Previous
          </button>
        </li>
        {pages.map((p, i) =>
          p === "…" ? (
            <li key={`gap-${i}`} aria-hidden="true" className="eui-pagination__gap">
              …
            </li>
          ) : (
            <li key={p}>
              <button
                type="button"
                className="eui-pagination__page"
                aria-label={`Page ${p}`}
                aria-current={p === page ? "page" : undefined}
                onClick={() => onPageChange(p)}
              >
                {p}
              </button>
            </li>
          ),
        )}
        <li>
          <button
            type="button"
            className="eui-pagination__control"
            disabled={page >= pageCount}
            onClick={() => onPageChange(page + 1)}
          >
            Next
          </button>
        </li>
      </ul>
    </nav>
  );
}

/** Returns page numbers with "…" gaps, always keeping the first and last page. */
export function buildRange(page: number, pageCount: number, siblings: number): (number | "…")[] {
  const out: (number | "…")[] = [];
  const left = Math.max(2, page - siblings);
  const right = Math.min(pageCount - 1, page + siblings);
  out.push(1);
  if (left > 2) out.push("…");
  for (let p = left; p <= right; p++) out.push(p);
  if (right < pageCount - 1) out.push("…");
  if (pageCount > 1) out.push(pageCount);
  return out;
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Pagination. Square buttons with the current page marked by a surface and ring. */

.eui-pagination__list {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.eui-pagination__control,
.eui-pagination__page {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 36px;
  height: 36px;
  padding: 0 10px;
  border: 0;
  border-radius: var(--eui-radius-base);
  background: transparent;
  color: var(--eui-color-fg);
  font-family: inherit;
  font-size: 14px;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}

.eui-pagination__control {
  box-shadow: inset 0 0 0 var(--eui-border-width) var(--eui-color-border-strong);
  font-weight: 500;
}

.eui-pagination__page:hover:not([aria-current="page"]),
.eui-pagination__control:hover:not(:disabled) {
  background-color: var(--eui-color-hover);
}

.eui-pagination__page[aria-current="page"] {
  background-color: var(--eui-color-surface);
  font-weight: 600;
  box-shadow: inset 0 0 0 var(--eui-border-width) var(--eui-color-fg-muted);
}

.eui-pagination__control:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.eui-pagination__control:focus-visible,
.eui-pagination__page:focus-visible {
  outline: 2px solid var(--eui-color-ring);
  outline-offset: 2px;
}

.eui-pagination__gap {
  min-width: 24px;
  text-align: center;
  color: var(--eui-color-fg-muted);
}
